from pathlib import Path

TSX = Path('src/modules/engineering/ui/GuidedMeasurementFlow.tsx')
CSS = Path('src/modules/engineering/ui/guided-measurement-flow.css')

s = TSX.read_text()

old_header = '''      <header><div><small>{originLabel(origin)}</small><h3>{stage.code?`${stage.code} · `:''}{stage.description}</h3><p>Marque os apartamentos/unidades deste serviço e confirme.</p></div><Button variant="secondary" size="sm" onClick={closeUnitPicker}>✕</Button></header>'''
new_header = '''      <header className="approved-unit-picker__header"><div><small>{originLabel(origin)}</small><h3>{stage.code?`${stage.code} · `:''}{stage.description}</h3><p>Selecione os apartamentos/unidades que receberão este serviço.</p></div><Button variant="secondary" size="sm" onClick={closeUnitPicker}>✕</Button></header>
      <section className="approved-unit-picker__summary"><div><span>Torre</span><strong>{originLabel(origin)}</strong><small>{refs.length?`${Math.max(1,Math.round(refs.length/Math.max(1,new Set(refs.map(referenceLevel)).size)))} apartamentos por pavimento`:'Serviço global'}</small></div><div><span>Serviço</span><strong>{stage.code||'—'}</strong><small>{currency.format(stage.unitPrice)} por unidade</small></div><div><span>Contratado</span><strong>{stage.contractedQuantity.toLocaleString('pt-BR')} un</strong><small>{currency.format(stage.contractedQuantity*stage.unitPrice)}</small></div><div><span>Já medido</span><strong>{previousQty.toLocaleString('pt-BR')} un</strong><small>{currency.format(previousQty*stage.unitPrice)}</small></div><div><span>Saldo</span><strong>{balance.toLocaleString('pt-BR')} un</strong><small>{currency.format(balance*stage.unitPrice)}</small></div></section>'''
if old_header in s:
    s = s.replace(old_header, new_header, 1)

old_bar = '''      <div className="guided-measurement-picker__bar">{refs.length>0?<><Input label="Pesquisar apartamento/unidade" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Ex.: 501"/><div><Button variant="secondary" onClick={()=>setSelectedUnits(available.slice(0,maxSelectable))}>Selecionar até {maxSelectable} disponível(is)</Button><Button variant="tertiary" onClick={()=>setSelectedUnits([])}>Limpar seleção</Button></div><p>Selecionadas: <strong>{selectedUnits.length}/{maxSelectable}</strong>.</p></>:<Input label="Quantidade nesta medição" value={manualQuantity} onChange={event=>setManualQuantity(event.target.value)} inputMode="decimal" placeholder="0,00"/>}</div>'''
new_bar = '''      <div className="guided-measurement-picker__bar approved-unit-picker__toolbar">{refs.length>0?<><Input label="Buscar apartamento" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar apartamento (ex.: 101, 203, 401...)"/><Button variant="secondary" onClick={()=>setSelectedUnits([])}>Limpar seleção</Button><p><span>Selecionados:</span> <strong>{selectedUnits.length} un</strong><br/><span>Valor total:</span> <strong>{currency.format(selectedUnits.length*stage.unitPrice)}</strong></p></>:<Input label="Quantidade nesta medição" value={manualQuantity} onChange={event=>setManualQuantity(event.target.value)} inputMode="decimal" placeholder="0,00"/>}</div>'''
if old_bar in s:
    s = s.replace(old_bar, new_bar, 1)

old_floors = '''      {refs.length>0&&<div className="guided-measurement-picker__list guided-measurement-picker__list--floors">{grouped.map(([level,references])=><section className="guided-measurement-floor" key={level}><header><strong>{referenceLevelLabel(level)}</strong><span>{references.filter(reference=>selectedUnits.includes(reference)).length}/{references.length} selecionado(s)</span></header><div className="guided-measurement-floor__units">{references.map(reference=><label key={reference} className={selectedUnits.includes(reference)?'is-selected':''}><input type="checkbox" checked={selectedUnits.includes(reference)} disabled={!selectedUnits.includes(reference)&&selectedUnits.length>=maxSelectable} onChange={()=>setSelectedUnits(current=>current.includes(reference)?current.filter(item=>item!==reference):(current.length<maxSelectable?[...current,reference]:current))}/><span>{reference.startsWith('TR-')?`Apto ${reference.slice(3)}`:`Apto ${reference}`}</span></label>)}</div></section>)}</div>}'''
new_floors = '''      {refs.length>0&&<div className="guided-measurement-picker__list guided-measurement-picker__list--floors approved-unit-picker__floors">{grouped.map(([level,references])=>{const selectedOnFloor=references.filter(reference=>selectedUnits.includes(reference)).length;const allSelected=references.length>0&&selectedOnFloor===references.length;return <section className="guided-measurement-floor approved-unit-picker__floor" key={level}><header><div><strong>{referenceLevelLabel(level)}</strong><Button variant="secondary" size="sm" onClick={()=>setSelectedUnits(current=>{if(allSelected)return current.filter(item=>!references.includes(item));const next=[...current];for(const reference of references){if(next.length>=maxSelectable)break;if(!next.includes(reference))next.push(reference);}return next;})}>{allSelected?'Desmarcar andar':'Selecionar todos'}</Button></div><span>{selectedOnFloor}/{references.length} selecionado(s)</span></header><div className="guided-measurement-floor__units">{references.map(reference=><label key={reference} className={selectedUnits.includes(reference)?'is-selected':''}><input type="checkbox" checked={selectedUnits.includes(reference)} disabled={!selectedUnits.includes(reference)&&selectedUnits.length>=maxSelectable} onChange={()=>setSelectedUnits(current=>current.includes(reference)?current.filter(item=>item!==reference):(current.length<maxSelectable?[...current,reference]:current))}/><span>{reference.startsWith('TR-')?reference.slice(3):reference}</span></label>)}</div></section>})}</div>}'''
if old_floors in s:
    s = s.replace(old_floors, new_floors, 1)

old_footer = '''      <footer><Button variant="secondary" onClick={closeUnitPicker}>Cancelar</Button><Button onClick={()=>void confirmSelection()} disabled={saving||(effectiveQuantity<=0&&currentLines.length===0)}>{saving?'Salvando…':'✓ Confirmar seleção'}</Button></footer>'''
new_footer = '''      <footer className="approved-unit-picker__footer"><div><strong>Resumo da seleção</strong><span>{selectedUnits.length>0?`${selectedUnits.length} unidade(s) · ${currency.format(selectedUnits.length*stage.unitPrice)}`:'Selecione os apartamentos para ver o resumo.'}</span></div><Button variant="secondary" onClick={()=>setSelectedUnits([])} disabled={selectedUnits.length===0}>Limpar seleção</Button><Button onClick={()=>void confirmSelection()} disabled={saving||(effectiveQuantity<=0&&currentLines.length===0)}>{saving?'Salvando…':'✓ Confirmar seleção'}</Button></footer>'''
if old_footer in s:
    s = s.replace(old_footer, new_footer, 1)

TSX.write_text(s)

css = CSS.read_text()
marker = '/* Approved unit picker 2026-09-07 */'
if marker not in css:
    css += r'''

/* Approved unit picker 2026-09-07 */
.guided-measurement-unit-picker .guided-measurement-picker__panel{grid-template-rows:auto auto auto minmax(0,1fr) auto;background:#f7faff}.approved-unit-picker__header{background:#fff;padding:18px 22px!important}.approved-unit-picker__header h3{font-size:1.25rem!important}.approved-unit-picker__summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;padding:14px 22px;background:#fff;border-bottom:1px solid #e2e8f0}.approved-unit-picker__summary>div{min-width:0;border:1px solid #dfe7f1;border-radius:16px;background:#fff;padding:13px 14px;display:grid;gap:4px;box-shadow:0 5px 16px rgba(15,23,42,.035)}.approved-unit-picker__summary span{font-size:.75rem;font-weight:800;color:#64748b}.approved-unit-picker__summary strong{font-size:1rem;color:#14243d;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.approved-unit-picker__summary small{color:#64748b;font-weight:700}.approved-unit-picker__toolbar{grid-template-columns:minmax(320px,1fr) auto minmax(210px,auto)!important;align-items:end;gap:10px!important;padding:12px 22px!important;background:#f7faff!important;border-bottom:1px solid #e2e8f0}.approved-unit-picker__toolbar>div{display:block!important}.approved-unit-picker__toolbar>p{min-height:44px;display:flex;align-items:center;gap:6px;justify-content:flex-end!important;flex-wrap:wrap;padding:7px 12px!important}.approved-unit-picker__floors{padding:12px 22px 18px!important;gap:10px!important}.approved-unit-picker__floor{border-radius:16px!important;background:#fff!important;padding:12px 14px!important;box-shadow:0 4px 14px rgba(15,23,42,.035)}.approved-unit-picker__floor>header>div{display:flex;align-items:center;gap:12px}.approved-unit-picker__floor>header button{min-height:34px;padding:0 12px}.approved-unit-picker__floor .guided-measurement-floor__units{grid-template-columns:repeat(8,minmax(92px,1fr));gap:8px}.approved-unit-picker__floor .guided-measurement-floor__units label{min-height:44px!important;border-radius:10px!important;padding:0 11px!important;font-size:.9rem!important}.approved-unit-picker__floor .guided-measurement-floor__units label.is-selected{border-color:#1769d2;background:#edf5ff;box-shadow:inset 0 0 0 1px #1769d2}.approved-unit-picker__floor .guided-measurement-floor__units input{width:18px!important;height:18px!important}.approved-unit-picker__footer{display:grid!important;grid-template-columns:minmax(220px,1fr) auto auto;align-items:center;gap:10px!important;padding:12px 22px!important;background:#fff}.approved-unit-picker__footer>div{display:grid;gap:2px}.approved-unit-picker__footer>div span{color:#64748b;font-size:.82rem}.approved-unit-picker__footer button{width:auto!important;min-height:46px!important;min-width:180px}@media(max-width:1000px){.approved-unit-picker__summary{grid-template-columns:repeat(2,minmax(0,1fr))}.approved-unit-picker__toolbar{grid-template-columns:1fr auto!important}.approved-unit-picker__toolbar>p{grid-column:1/-1;justify-content:flex-start!important}.approved-unit-picker__floor .guided-measurement-floor__units{grid-template-columns:repeat(4,minmax(100px,1fr))}}@media(max-width:640px){.approved-unit-picker__summary{grid-template-columns:1fr 1fr;padding:10px 12px}.approved-unit-picker__toolbar{grid-template-columns:1fr!important;padding:10px 12px!important}.approved-unit-picker__toolbar>p{grid-column:auto}.approved-unit-picker__floors{padding:10px 12px 90px!important}.approved-unit-picker__floor>header{align-items:flex-start}.approved-unit-picker__floor>header>div{align-items:flex-start;flex-direction:column;gap:7px}.approved-unit-picker__floor .guided-measurement-floor__units{grid-template-columns:repeat(2,minmax(0,1fr))}.approved-unit-picker__footer{position:fixed;left:0;right:0;bottom:0;z-index:10;grid-template-columns:1fr 1fr;padding:10px 12px!important}.approved-unit-picker__footer>div{grid-column:1/-1}.approved-unit-picker__footer button{min-width:0!important;width:100%!important}}
'''
    CSS.write_text(css)
